  "The gateway picks the lowest priority number that is enabled, supports the session language, and has a credential. A provider that is enabled but has no key is": "تختار البوابة أقل رقم أولوية مفعّل يدعم لغة الجلسة ولديه بيانات اعتماد. المزوّد المفعّل بلا مفتاح يكون",
  "This adapter has never run against its provider in this build. Treat anything below as illustrative, not as a transcript.": "لم يعمل هذا المحول مع مزوّده في هذا البناء. اعتبر ما يلي توضيحياً وليس نصاً مفرّغاً.",
  "This derives a level from what is already documented.": "يستنتج مستوى مما وُثّق بالفعل.",
  "This document is a tax invoice issued under UAE VAT rules. Values are expressed in AED.": "هذا المستند فاتورة ضريبية صادرة وفق قواعد ضريبة القيمة المضافة الإماراتية. القيم بالدرهم الإماراتي.",
  "This is a clinical use case. I confirm the fields above may be sent for record": "هذه حالة استخدام سريرية. أؤكد السماح بإرسال الحقول أعلاه للسجل",
