  "Verify": "تحقق",
  "Verifying and removing both reach the provider or the store, so both are audited and both count against the rate limit below. Removing cannot be undone from here — the old value is unreadable by design.": "التحقق والحذف يصلان للمزوّد أو المخزن، لذلك يُدقّقان ويُحتسبان ضمن حد المعدل. لا يمكن التراجع عن الحذف هنا لأن القيمة القديمة غير قابلة للقراءة.",
  "View analysis": "عرض التحليل",
  "Write-only. The value is never returned by any endpoint, so it cannot be shown here or checked by eye — the last four characters and a fingerprint are what distinguish one key from another. Use": "للكتابة فقط. لا تعيد أي نقطة نهاية القيمة فلا يمكن عرضها أو فحصها بصرياً؛ تميّز المفاتيح بآخر أربعة أحرف وبصمة. استخدم",
